readonly visibleEditableColumns = computed(() => {
  const result = this.editableColumns().filter(c => !this.hideEligibilityEditorColumn(c) && !this.isHiddenBusinessField(c));
  // Match reference HTML and RTL reading order, independent of Oracle physical column order.
  if (this.tableName() === 'LOAN_PRODUCT_REPAYMENT_RULE') {
    // Only reorder the contiguous term section; preserve the rest of Oracle metadata order.
    const start = result.findIndex(c => c.name === 'MIN_TERM_DURATION');
    const end = result.findIndex(c => c.name === 'MAX_INSTALLMENT_COUNT');
    const unit = result.find(c => c.name === 'TERM_UNIT_CODE');
    if (start >= 0 && end >= start && unit) {
      const other = result.filter(c => c.name !== 'TERM_UNIT_CODE');
      const at = other.findIndex(c => c.name === 'MIN_TERM_DURATION');
      if (at >= 0) other.splice(at, 0, unit);
      return other;
    }
  }
  return this.tableName() === 'DEPOSIT_PRODUCT_DORMANCY_RULE'
    ? [...result].sort((a, b) => (DORMANCY_FIELD_ORDER[a.name] ?? 1000) - (DORMANCY_FIELD_ORDER[b.name] ?? 1000))
    : result;
});

