isCustomerContribution(column: PdlColumnDescriptor): boolean {
  return this.tableName() === 'LOAN_FINANCIAL_EXTENSION' && LOAN_PARTICIPATION_FIELDS.includes(column.name as typeof LOAN_PARTICIPATION_FIELDS[number]);
}
contributionPercentText(column: PdlColumnDescriptor): string {
  const raw = this.form.controls[column.name]?.value;
  if (raw == null || raw === '') return '';
  const number = Number(raw) * 100;
  return Number.isFinite(number) ? String(Number(number.toFixed(4))) : '';
}
onContributionPercentInput(column: PdlColumnDescriptor, event: Event): void {
  const element = event.target as HTMLInputElement;
  const text = this.normalizeDigits(element.value).replace(/[٫،]/g, '.').trim();
  if (!text) { this.form.controls[column.name]?.setValue(null); return; }
  const percentage = Number(text);
  this.form.controls[column.name]?.setValue(!Number.isFinite(percentage) ? null :
    (percentage < 0 || percentage > 100 ? percentage / 100 : Number((percentage / 100).toFixed(6))));
}
toggleLoanContribution(checked: boolean): void {
  if (checked && this.loanCivilParticipation() !== true) return;
  this.loanContributionEnabled.setValue(checked);
  this.syncLoanContributionFields(!checked);
}
private syncLoanContributionFields(clearWhenOff = false): void {
  if (this.tableName() !== 'LOAN_FINANCIAL_EXTENSION') return;
  const on = this.loanCivilParticipation() === true && this.loanContributionEnabled.value;
  for (const key of LOAN_PARTICIPATION_FIELDS) {
    const input = this.form.controls[key];
    if (!input) continue;
    if (on) input.enable({emitEvent: false});
    else {
      if (clearWhenOff) input.setValue(null, {emitEvent: false});
      input.disable({emitEvent: false});
    }
  }
}
/** Never infer "civil partnership" from the participatory group alone. */
private isCivilPartnershipReference(row: Readonly<Record<string, any>>): boolean {
  if (Number(row['LOAN_GROUP']) !== 3) return false;
  const title = String(row['LOAN_TYPE_NAME'] ?? '').replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/\u200c/g, ' ').replace(/\s+/g, ' ').trim();
  const code = String(row['LOAN_TYPE_CODE'] ?? '').trim().toUpperCase();
  return title === 'مشارکت مدنی' || ['CIVIL_PARTNERSHIP','MOSHAREKAT_MADANI','MOSHAREKAT-MADANI'].includes(code);
}
private async loadLoanContributionContext(): Promise<void> {
  if (this.tableName() !== 'LOAN_FINANCIAL_EXTENSION') return;
  this.loanCivilParticipation.set(null);
  this.loanContributionIssue.set(null);
  this.syncLoanContributionFields();
  const version = Number(this.form.controls['PRODUCT_VERSION_ID']?.value);
  if (!Number.isSafeInteger(version) || version < 1) {
    this.loanContributionIssue.set('ابتدا نسخه محصول را مشخص کنید؛ سهم مشتری فقط برای عقد مشارکت مدنی تعریف می‌شود.');
    return;
  }
  try {
    const rows = await this.service.rows('LOAN_PRODUCT_PROFILE', {page:0, size:2, filterColumn:'PRODUCT_VERSION_ID', filterValue:version});
    if (this.tableName() !== 'LOAN_FINANCIAL_EXTENSION' || Number(this.form.controls['PRODUCT_VERSION_ID']?.value) !== version) return;
    if (rows.totalElements !== 1 || rows.items.length !== 1) {
      this.loanCivilParticipation.set(false);
      this.loanContributionIssue.set('برای تعریف آورده مشتری، ابتدا پروفایل و نوع عقد این نسخه را ثبت کنید.');
      this.syncLoanContributionFields();
      return;
    }
    const typeId = Number(rows.items[0]['LOAN_TYPE_ID']);
    const type = await this.service.row('LOAN_TYPE', typeId);
    if (this.tableName() !== 'LOAN_FINANCIAL_EXTENSION' || Number(this.form.controls['PRODUCT_VERSION_ID']?.value) !== version) return;
    const allowed = this.isCivilPartnershipReference(type);
    this.loanCivilParticipation.set(allowed);
    if (!allowed) this.loanContributionIssue.set('این عقد مشارکت مدنی نیست؛ سهم / آورده مشتری برای آن کاربرد ندارد.');
    this.syncLoanContributionFields();
  } catch (e) {
    this.loanCivilParticipation.set(false);
    this.loanContributionIssue.set('تشخیص نوع عقد برای آورده مشتری موفق نبود: ' + this.message(e));
    this.syncLoanContributionFields();
  }
}

