/** Grid labels must not depend on a capped active-only lookup; historical FK IDs also resolve. */
private async resolveLoanGridReferenceNames(
  table: string, items: readonly Readonly<Record<string, any>>[], generation: number
): Promise<void> {
  const columns = table === 'LOAN_PRODUCT_PROFILE' ? LOAN_PROFILE_GRID_FIELDS : ['LOAN_PRODUCT_COLLATERAL_ID'];
  const requested: {column: string; id: number; key: string}[] = [];
  for (const row of items) for (const column of columns) {
    const parent = LOAN_GRID_PARENTS[column];
    if (!parent) continue;
    const id = Number(row[column]);
    if (!Number.isSafeInteger(id) || id < 1) continue;
    const key = `${column}:${id}`;
    if (this.loanGridReferenceNames()[key] || this.pendingLoanGridReferences.has(key) ||
        (this.lookupOptions()[column] ?? []).some(option => Number(option.value) === id)) continue;
    this.pendingLoanGridReferences.add(key);
    requested.push({column, id, key});
  }
  await Promise.all(requested.map(async ({column, id, key}) => {
    let label = 'اطلاعات مرجع این رکورد یافت نشد';
    try {
      const record = await this.service.row(LOAN_GRID_PARENTS[column], id);
      const nameKey: Readonly<Record<string, string>> = {
        LOAN_TYPE_ID: 'LOAN_TYPE_NAME', PLAN_TYPE_ID: 'PLAN_TYPE_NAME',
        LOAN_USAGE_ID: 'LOAN_USAGE_NAME', ECONOMIC_SUB_SECTION_ID: 'ECONOMIC_SUB_SECTION_NAME',
        LOAN_PRODUCT_COLLATERAL_ID: 'PRODUCT_COLLATERAL_NAME'
      };
      if (column === 'OPERATION_PARAMETER_ID') {
        label = `سررسید گذشته ${record['OVERDUE_DURATION'] ?? '—'}، معوق ${record['PASTDUE_DURATION'] ?? '—'}، مشکوک‌الوصول ${record['DOUBTFUL_DURATION'] ?? '—'} روز`;
      } else {
        const name = String(record[nameKey[column]] ?? '').trim();
        if (name) label = name;
      }
    } catch { /* No fake FK title; show an explicit unresolved-reference notice. */ }
    this.pendingLoanGridReferences.delete(key);
    if (generation === this.navigationGeneration && table === this.tableName())
      this.loanGridReferenceNames.update(current => ({...current, [key]: label}));
  }));
}

